/**
 * Mapping of objective measurements onto clinician-familiar scales.
 *
 * PROVISIONAL: every cut-off below is an engineering prior chosen from the
 * literature on facial landmark asymmetry. They are frozen per SCORING_VERSION
 * and must be re-calibrated against blinded expert ratings in the clinical
 * validation study (docs/07-verification-validation-plan.md) before any
 * diagnostic claim is made.
 */
import { SCORING_VERSION } from './version';
import type { HouseBrackmannGrade, MovementTaskId, RestMeasurement, Scores, TaskMeasurement } from './types';
import { mean } from './stats';

export const SCORING = Object.freeze({
  version: SCORING_VERSION,
  /** ratio < cut[i] → voluntary grade i+1; otherwise 5. */
  voluntaryCuts: [0.15, 0.4, 0.7, 0.9] as const,
  /** |aperture ratio − 1| ≥ this → resting eye item = 1. */
  restEyeRatioDeviation: 0.18,
  /** mid-face drop (face units) ≥ cut → cheek item 1 / 2. */
  restCheekCuts: [0.035, 0.07] as const,
  /** |mouth-corner level difference| ≥ this → mouth item = 1. */
  restMouthCut: 0.035,
  /** Synkinesis grade cut-offs: eye-narrowing fraction and mouth displacement (face units). */
  synkEyeCuts: [0.12, 0.25, 0.45] as const,
  synkMouthCuts: [0.025, 0.05, 0.08] as const,
  /** Healthy-side excursion below this means the task was not performed. */
  minHealthyExcursion: { brow: 0.02, eyeClose: 0.35, smile: 0.03, snarl: 0.012, pucker: 0.02 } as Record<MovementTaskId, number>,
  /** Eye closure counts as complete when ratio ≥ this AND residual gap difference ≤ max. */
  eyeClosureCompleteRatio: 0.85,
  eyeClosureMaxResidualDiff: 0.03,
  /**
   * Measured and stored, but left out of every score and of the side check: on the synthetic
   * bench (tools/blender/BENCH.md) the landmark model does not follow lip pucker at all (ratio
   * 1.57 with no movement on the weak side). Its synkinesis item (eye narrowing) is kept.
   */
  excludedTasks: ['pucker'] as readonly MovementTaskId[],
  /** Shown as reference only (bench error ≈ 0.28, 5× the target). */
  lowConfidenceTasks: ['snarl'] as readonly MovementTaskId[],
});

export const isScoredTask = (t: MovementTaskId): boolean => !SCORING.excludedTasks.includes(t);

export function voluntaryGrade(ratio: number): 1 | 2 | 3 | 4 | 5 {
  const c = SCORING.voluntaryCuts;
  if (ratio < c[0]) return 1;
  if (ratio < c[1]) return 2;
  if (ratio < c[2]) return 3;
  if (ratio < c[3]) return 4;
  return 5;
}

export function synkinesisGrade(task: MovementTaskId, index: number): 0 | 1 | 2 | 3 {
  const c = task === 'brow' || task === 'eyeClose' ? SCORING.synkMouthCuts : SCORING.synkEyeCuts;
  if (index < c[0]) return 0;
  if (index < c[1]) return 1;
  if (index < c[2]) return 2;
  return 3;
}

export function restItems(m: Omit<RestMeasurement, 'items'>): RestMeasurement['items'] {
  const eye = Math.abs(m.eyeApertureRatio - 1) >= SCORING.restEyeRatioDeviation ? 1 : 0;
  const cheek = m.midfaceDrop >= SCORING.restCheekCuts[1] ? 2 : m.midfaceDrop >= SCORING.restCheekCuts[0] ? 1 : 0;
  const mouth = Math.abs(m.mouthCornerDrop) >= SCORING.restMouthCut ? 1 : 0;
  return { eye, cheek, mouth };
}

export function isEyeClosureComplete(m: TaskMeasurement, affected: 'left' | 'right'): boolean {
  const gapAff = affected === 'left' ? m.extras.residualGapLeft! : m.extras.residualGapRight!;
  const gapHealthy = affected === 'left' ? m.extras.residualGapRight! : m.extras.residualGapLeft!;
  return m.ratio >= SCORING.eyeClosureCompleteRatio && gapAff - gapHealthy <= SCORING.eyeClosureMaxResidualDiff;
}

/**
 * Rule-based House–Brackmann estimate. Rules are evaluated from most to least
 * severe; the first rule that fires determines the grade and is reported
 * (ruleId) so the result is explainable and auditable.
 */
export function estimateHouseBrackmann(input: {
  ratios: Partial<Record<MovementTaskId, number>> & { brow: number };
  eyeClosureComplete: boolean;
  synkinesisScore: number;
  restScore: number;
}): { grade: HouseBrackmannGrade; ruleId: string } {
  const r = Object.values(input.ratios).map((x) => Math.min(1, x!));
  const meanR = mean(r);
  const maxR = Math.max(...r);
  const minR = Math.min(...r);
  const brow = Math.min(1, input.ratios.brow);
  if (maxR < 0.1) return { grade: 6, ruleId: 'HB6-no-movement' };
  if (meanR < 0.3) return { grade: 5, ruleId: 'HB5-barely-perceptible' };
  if (!input.eyeClosureComplete) return { grade: 4, ruleId: 'HB4-incomplete-eye-closure' };
  if (brow < 0.1) return { grade: 4, ruleId: 'HB4-no-forehead-movement' };
  if (meanR < 0.55) return { grade: 4, ruleId: 'HB4-obvious-weakness' };
  if (meanR < 0.8) return { grade: 3, ruleId: 'HB3-moderate-weakness' };
  if (brow < 0.5) return { grade: 3, ruleId: 'HB3-reduced-forehead' };
  if (input.synkinesisScore >= 4) return { grade: 3, ruleId: 'HB3-noticeable-synkinesis' };
  if (meanR < 0.95 || minR < 0.85) return { grade: 2, ruleId: 'HB2-slight-weakness' };
  if (input.synkinesisScore >= 1 || input.restScore > 0) return { grade: 2, ruleId: 'HB2-slight-asymmetry' };
  return { grade: 1, ruleId: 'HB1-normal' };
}

/**
 * `tasks` must hold every scored task (see SCORING.excludedTasks); excluded ones may be absent.
 * Sunnybrook voluntary movement has five items: with an excluded task, the scored items are
 * scaled up to the five-item range (4 · Σgrade · 5 / n) so the composite keeps its 0–100 span.
 */
export function computeScores(
  rest: RestMeasurement,
  tasks: Partial<Record<MovementTaskId, TaskMeasurement>> & Record<'brow' | 'eyeClose' | 'smile', TaskMeasurement>,
  affected: 'left' | 'right',
): Scores {
  const list = Object.values(tasks) as TaskMeasurement[];
  const scored = list.filter((t) => isScoredTask(t.task));
  const restScore = 5 * (rest.items.eye + rest.items.cheek + rest.items.mouth);
  const voluntaryScore = Math.round((4 * scored.reduce((s, t) => s + t.grade, 0) * 5) / scored.length);
  const synkinesisScore = list.reduce((s, t) => s + t.synkinesisGrade, 0);
  const composite = Math.max(0, Math.min(100, voluntaryScore - restScore - synkinesisScore));
  const ratios = Object.fromEntries(scored.map((t) => [t.task, t.ratio])) as Partial<Record<MovementTaskId, number>> & { brow: number };
  const eyeClosureComplete = isEyeClosureComplete(tasks.eyeClose, affected);
  const pct = (x: number): number => Math.round(Math.min(1, x) * 100);
  return {
    restScore,
    voluntaryScore,
    synkinesisScore,
    composite,
    houseBrackmann: estimateHouseBrackmann({ ratios, eyeClosureComplete, synkinesisScore, restScore }),
    functionIndex: Math.round(mean(scored.map((t) => Math.min(1, t.ratio))) * 100),
    regional: {
      forehead: pct(ratios.brow),
      eye: pct(ratios.eyeClose!),
      midface: pct(ratios.snarl ?? 0),
      mouth: pct(ratios.smile!),
    },
    eyeClosureComplete,
  };
}

export const HB_ROMAN = ['', 'I', 'II', 'III', 'IV', 'V', 'VI'] as const;

/** Clinician-entered Sunnybrook items (Ross et al. 1996). */
export interface SunnybrookItems {
  rest: { eye: number; cheek: number; mouth: number };
  voluntary: Record<MovementTaskId, number>;
  synkinesis: Record<MovementTaskId, number>;
}

/** Sunnybrook composite = 4·Σvoluntary − 5·Σrest − Σsynkinesis (unclamped, as published). */
export function sunnybrookComposite(i: SunnybrookItems): number {
  const tasks = Object.keys(i.voluntary) as MovementTaskId[];
  const rest = 5 * (i.rest.eye + i.rest.cheek + i.rest.mouth);
  const vol = 4 * tasks.reduce((s, t) => s + i.voluntary[t], 0);
  const syn = tasks.reduce((s, t) => s + i.synkinesis[t], 0);
  return vol - rest - syn;
}
