/**
 * Optional assessment photos (profile.savePhotos, off by default): one JPEG per step, on this device only,
 * stored apart from the sealed session record and never part of an export. "Delete all data" removes them too.
 */
import { db } from './db';
import type { SessionSnapshots } from './types';

/** Longest side of a stored photo (px). */
export const SNAPSHOT_MAX_PX = 480;

export const saveSnapshots = (s: SessionSnapshots) => db.put('snapshots', s);
export const loadSnapshots = (sessionId: string) => db.get<SessionSnapshots>('snapshots', sessionId);
export const countSnapshots = () => db.count('snapshots');
export const deleteAllSnapshots = () => db.clear('snapshots');

/** Canvas holding one frame of `src`, scaled so its longest side is SNAPSHOT_MAX_PX (camera orientation). */
export function drawSnapshot(src: HTMLVideoElement, into?: HTMLCanvasElement): HTMLCanvasElement | null {
  const [w0, h0] = [src.videoWidth, src.videoHeight];
  if (!w0 || !h0) return null;
  const k = Math.min(1, SNAPSHOT_MAX_PX / Math.max(w0, h0));
  const c = into ?? document.createElement('canvas');
  c.width = Math.round(w0 * k);
  c.height = Math.round(h0 * k);
  c.getContext('2d')?.drawImage(src, 0, 0, c.width, c.height);
  return c;
}

export const toJpeg = (c: HTMLCanvasElement): Promise<Blob | null> => new Promise((res) => c.toBlob(res, 'image/jpeg', 0.82));
