/** "발병 N일째" with the onset day counted as day 1 (stored values are days since onset, 0-based). */
export const dayLabel = (daysSinceOnset: number): string => `발병 ${daysSinceOnset + 1}일째`;

export const fmtDate = (iso: string): string => {
  const d = new Date(iso);
  return `${d.getFullYear()}.${d.getMonth() + 1}.${d.getDate()}`;
};

export const fmtDateTime = (iso: string): string => {
  const d = new Date(iso);
  const z = (n: number) => String(n).padStart(2, '0');
  return `${fmtDate(iso)} ${z(d.getHours())}:${z(d.getMinutes())}`;
};
